#!/bin/sh
# Generated by FWShift - review the conversion report before running this.
#
# Check Point Management API calls (mgmt_cli): objects, the rules of access layer
# 'Network' and the NAT rules of policy package 'Standard'.
#
# 1. Log in and keep the session in a file:
#        mgmt_cli login -r true > fwshift.sid          (as root on the management server)
#        mgmt_cli login user <admin> > fwshift.sid     (anywhere else; add -m <server>)
# 2. Run this script:  sh <this file>
# 3. Look at the session in SmartConsole. Nothing is published or installed here:
#        mgmt_cli publish -s fwshift.sid       to keep the changes
#        mgmt_cli discard -s fwshift.sid       to throw them away
#
# The script stops at the first call the server refuses. Discard the session, fix
# the cause and run it again: a policy with rules missing is not a safe policy.
#
# SID        session file (default fwshift.sid)
# MGMT_OPTS  extra switches for every call, for example: MGMT_OPTS='-m 192.0.2.10'

SID="${SID:-fwshift.sid}"

m() {
    if ! out=$(mgmt_cli "$@" $MGMT_OPTS -s "$SID" 2>&1); then
        printf 'FAILED: mgmt_cli %s\n%s\n' "$*" "$out" >&2
        printf 'Stopped. Nothing was published. Undo with: mgmt_cli discard -s %s\n' "$SID" >&2
        exit 1
    fi
}

# A zone has no content of its own: one that exists already is used as it is.
zone() {
    mgmt_cli show security-zone name "$1" $MGMT_OPTS -s "$SID" >/dev/null 2>&1 || m add security-zone name "$1" ignore-warnings true
}

# Network objects
m add network name bad-net subnet 198.51.100.0 mask-length 24 ignore-warnings true
m add host name bad-host ip-address 192.0.2.66 ignore-warnings true
m add network name v6-net subnet 2001:db8:10:: mask-length 48 ignore-warnings true
m add network name lan-net subnet 10.10.0.0 mask-length 16 ignore-warnings true
m add dns-domain name .updates.example.com is-sub-domain false ignore-warnings true
m add host name web-srv ip-address 10.20.0.80 ignore-warnings true
m add host name mail-srv ip-address 10.20.0.25 ignore-warnings true
m add address-range name admin-range ip-address-first 10.10.5.10 ip-address-last 10.10.5.20 ignore-warnings true
m add network name dmz-net__dmz-book_ subnet 10.20.0.0 mask-length 24 ignore-warnings true
m add network name lan-net__dmz-book_ subnet 10.20.0.64 mask-length 26 ignore-warnings true
m add group name bad members.1 bad-net members.2 bad-host ignore-warnings true
m add group name watched members.1 bad members.2 v6-net ignore-warnings true
m add group name servers members.1 web-srv members.2 mail-srv ignore-warnings true

# Services
m add service-tcp name junos-http port 80 match-for-any false ignore-warnings true
m add service-tcp name junos-https port 443 match-for-any false ignore-warnings true
m add service-tcp name app-web-alt port 8080-8081 match-for-any false ignore-warnings true
m add service-icmp name app-ping icmp-type 8 ignore-warnings true
m add service-tcp name junos-smtp port 25 match-for-any false ignore-warnings true
m add service-tcp name app-mail-sub-tcp587 port 587 match-for-any false ignore-warnings true
m add service-tcp name app-mail-sub-tcp465 port 465 match-for-any false ignore-warnings true
m add service-group name app-mail-sub members.1 app-mail-sub-tcp587 members.2 app-mail-sub-tcp465 ignore-warnings true
m add service-tcp name junos-ssh port 22 match-for-any false ignore-warnings true
m add service-other name app-gre ip-protocol 47 match-for-any false ignore-warnings true
m add service-udp name junos-dns-udp port 53 match-for-any false ignore-warnings true
m add service-udp name app-ntp port 123 match-for-any false ignore-warnings true
m add service-group name junos-ping comments 'FWSHIFT PLACEHOLDER, matches nothing: the predefined application junos-ping: Juniper describes it as ICMP echo, other readers of Junos as every ICMP type' ignore-warnings true
m add service-tcp name app-high port 1000-2000 source-port 1024-65535 match-for-any false ignore-warnings true
m add service-tcp name NAT_from-internet_dnat-web-tcp80 port 80 match-for-any false ignore-warnings true
m add service-udp name NAT_from-internet_dnat-web-udp80 port 80 match-for-any false ignore-warnings true
m add service-group name NAT_from-internet_dnat-web members.1 NAT_from-internet_dnat-web-tcp80 members.2 NAT_from-internet_dnat-web-udp80 ignore-warnings true
m add service-group name web-all members.1 junos-http members.2 junos-https members.3 app-web-alt ignore-warnings true
m add host name h-203.0.113.10 ip-address 203.0.113.10 ignore-warnings true
m add host name h-203.0.113.25 ip-address 203.0.113.25 ignore-warnings true
m add address-range name All-IPv4 ip-address-first 0.0.0.0 ip-address-last 255.255.255.255 ignore-warnings true

# Security zones
zone trust
zone untrust
zone dmz
zone guest

# Traffic from zone trust to zone untrust
m add access-layer name Network_trust_to_untrust add-default-rule false ignore-warnings true
m add access-rule layer Network_trust_to_untrust position bottom name block-bad source.1 Any destination.1 watched service.1 Any action Drop track.type Log ignore-warnings true
m add access-rule layer Network_trust_to_untrust position bottom name web-out source.1 lan-net destination.1 Any service.1 web-all action Accept track.type Log comments 'web for the office' ignore-warnings true
m add access-rule layer Network_trust_to_untrust position bottom name updates source.1 lan-net destination.1 .updates.example.com service.1 junos-https action Accept track.type None ignore-warnings true
m add access-rule layer Network_trust_to_untrust position bottom name ping-out source.1 trust destination.1 untrust service.1 app-ping action Accept track.type None ignore-warnings true
m add access-rule layer Network_trust_to_untrust position bottom name global-block source.1 bad destination.1 Any service.1 Any action Reject track.type None ignore-warnings true
m add access-rule layer Network_trust_to_untrust position bottom name global-ntp source.1 trust destination.1 untrust service.1 app-ntp service.2 app-high action Accept track.type None ignore-warnings true
m add access-rule layer Network_trust_to_untrust position bottom name 'FWShift cleanup' source.1 Any destination.1 Any service.1 Any action Drop track.type Log comments 'Added by FWShift: the source drops what no rule allows.' ignore-warnings true
m add access-rule layer Network position 1 name 'trust to untrust' source.1 trust destination.1 untrust service.1 Any action 'Apply Layer' inline-layer Network_trust_to_untrust ignore-warnings true

# Traffic from zone trust to zone dmz
m add access-layer name Network_trust_to_dmz add-default-rule false ignore-warnings true
m add access-rule layer Network_trust_to_dmz position bottom name admin source.1 admin-range destination.1 dmz-net__dmz-book_ service.1 junos-ssh action Accept track.type None ignore-warnings true
m add access-rule layer Network_trust_to_dmz position bottom name not-servers source.1 servers destination.1 lan-net__dmz-book_ service.1 app-gre source-negate true action Accept track.type None ignore-warnings true
m add access-rule layer Network_trust_to_dmz position bottom name global-block source.1 bad destination.1 Any service.1 Any action Reject track.type None ignore-warnings true
m add access-rule layer Network_trust_to_dmz position bottom name 'FWShift cleanup' source.1 Any destination.1 Any service.1 Any action Drop track.type Log comments 'Added by FWShift: the source drops what no rule allows.' ignore-warnings true
m add access-rule layer Network position 2 name 'trust to dmz' source.1 trust destination.1 dmz service.1 Any action 'Apply Layer' inline-layer Network_trust_to_dmz ignore-warnings true

# Traffic from zone untrust to zone dmz
m add access-layer name Network_untrust_to_dmz add-default-rule false ignore-warnings true
m add access-rule layer Network_untrust_to_dmz position bottom name web-in source.1 Any destination.1 web-srv destination.2 h-203.0.113.10 service.1 app-web-alt action Accept track.type None ignore-warnings true
m add access-rule layer Network_untrust_to_dmz position bottom name mail-in source.1 Any destination.1 mail-srv destination.2 h-203.0.113.25 service.1 junos-smtp service.2 app-mail-sub action Accept track.type None ignore-warnings true
m add access-rule layer Network_untrust_to_dmz position bottom name global-block source.1 bad destination.1 Any service.1 Any action Reject track.type None ignore-warnings true
m add access-rule layer Network_untrust_to_dmz position bottom name 'FWShift cleanup' source.1 Any destination.1 Any service.1 Any action Drop track.type Log comments 'Added by FWShift: the source drops what no rule allows.' ignore-warnings true
m add access-rule layer Network position 3 name 'untrust to dmz' source.1 untrust destination.1 dmz service.1 Any action 'Apply Layer' inline-layer Network_untrust_to_dmz ignore-warnings true

# Traffic from zone dmz to zone untrust
m add access-layer name Network_dmz_to_untrust add-default-rule false ignore-warnings true
m add access-rule layer Network_dmz_to_untrust position bottom name dmz-out source.1 dmz-net__dmz-book_ destination.1 Any service.1 junos-dns-udp service.2 app-ntp action Accept track.type None enabled false ignore-warnings true
m add access-rule layer Network_dmz_to_untrust position bottom name global-block source.1 bad destination.1 Any service.1 Any action Reject track.type None ignore-warnings true
m add access-rule layer Network_dmz_to_untrust position bottom name 'FWShift cleanup' source.1 Any destination.1 Any service.1 Any action Drop track.type Log comments 'Added by FWShift: the source drops what no rule allows.' ignore-warnings true
m add access-rule layer Network position 4 name 'dmz to untrust' source.1 dmz destination.1 untrust service.1 Any action 'Apply Layer' inline-layer Network_dmz_to_untrust ignore-warnings true

# Traffic from zone guest to zone untrust
m add access-layer name Network_guest_to_untrust add-default-rule false ignore-warnings true
m add access-rule layer Network_guest_to_untrust position bottom name guest-web source.1 Any destination.1 All-IPv4 service.1 junos-http action Accept track.type None enabled false comments 'FWSHIFT: disabled by the converter, see the report.' ignore-warnings true
m add access-rule layer Network_guest_to_untrust position bottom name guest-ping source.1 guest destination.1 untrust service.1 junos-ping action Accept track.type None enabled false comments 'FWSHIFT: disabled by the converter, see the report.' ignore-warnings true
m add access-rule layer Network_guest_to_untrust position bottom name global-block source.1 bad destination.1 Any service.1 Any action Reject track.type None ignore-warnings true
m add access-rule layer Network_guest_to_untrust position bottom name 'FWShift cleanup' source.1 Any destination.1 Any service.1 Any action Drop track.type Log comments 'Added by FWShift: the source drops what no rule allows.' ignore-warnings true
m add access-rule layer Network position 5 name 'guest to untrust' source.1 guest destination.1 untrust service.1 Any action 'Apply Layer' inline-layer Network_guest_to_untrust ignore-warnings true

# Rules of layer Network for traffic of no zone pair above
m add access-rule layer Network position 6 name ping-out source.1 trust destination.1 untrust service.1 app-ping action Accept track.type None ignore-warnings true
m add access-rule layer Network position 7 name guest-ping source.1 guest destination.1 untrust service.1 junos-ping action Accept track.type None enabled false comments 'FWSHIFT: disabled by the converter, see the report.' ignore-warnings true
m add access-rule layer Network position 8 name intra source.1 trust destination.1 trust service.1 Any action Accept track.type None ignore-warnings true
m add access-rule layer Network position 9 name global-block source.1 bad destination.1 Any service.1 Any action Reject track.type None ignore-warnings true
m add access-rule layer Network position 10 name global-ntp source.1 trust destination.1 untrust service.1 app-ntp service.2 app-high action Accept track.type None ignore-warnings true
m add access-rule layer Network position 11 name 'FWShift cleanup' source.1 Any destination.1 Any service.1 Any action Drop track.type Log comments 'Added by FWShift: the source drops what no rule allows.' ignore-warnings true

# NAT rules of package Standard
m add nat-rule package Standard position bottom original-source Any original-destination h-203.0.113.25 original-service Any translated-source Original translated-destination mail-srv translated-service Original method static comments inbound_static-mail ignore-warnings true
m add nat-rule package Standard position bottom original-source mail-srv original-destination Any original-service Any translated-source h-203.0.113.25 translated-destination Original translated-service Original method static comments inbound_static-mail__outbound_ ignore-warnings true

echo 'Done. Review the session, then publish or discard it.'
